</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++14 code you have to translate:
<original_code>
#include <iostream>
#include <vector>
#include <cmath>
using namespace std;

int gcd(int a, int b) {
    while (b != 0) {
        int temp = b;
        b = a % b;
        a = temp;
    }
    return a;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    double x, y, n;
    cin >> x >> y >> n;
    int a, b;
    double ratio = x / y;
    double min_diff = 1e9;
    int best_num = 0, best_den = 1;

    if (y <= n) {
        a = static_cast<int>(x);
        b = static_cast<int>(y);
    } else {
        for (int i = n; i >= 1; --i) {
            int denom = i;
            double val = denom * ratio;
            int num;
            if (val - floor(val) <= 0.5)
                num = static_cast<int>(floor(val));
            else
                num = static_cast<int>(floor(val)) + 1;
            double current = static_cast<double>(num) / denom;
            double diff = fabs(current - ratio);
            if (diff <= min_diff) {
                min_diff = diff;
                best_num = num;
                best_den = denom;
            }
        }
        a = best_num;
        b = best_den;
    }
    int g = gcd(a, b);
    a /= g;
    b /= g;
    cout << a << "/" << b << "\n";
    return 0;
}
